using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using FleetOps.Kernel;
using FleetOps.Modules.Documents;
using FleetOps.Modules.Fleet;
using Xunit;

namespace FleetOps.Tests;

public sealed class ReadinessApiTests : IAsyncLifetime
{
    private readonly VehicleApiFactory factory = new();

    public ValueTask InitializeAsync() => factory.InitializeAsync();
    public ValueTask DisposeAsync() => factory.DisposeAsync();

    [Fact] public async Task Vehicle_list_shows_the_derived_status() { var v = await VehicleWithDocuments(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2026, 11, 5)); using var response = await factory.AsDispatcher().GetAsync("/api/v1/fleet/vehicles"); var body = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync()); var row = body.RootElement.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == v.Id); Assert.Equal("off_road", row.GetProperty("shownStatus").GetString()); Assert.False(row.GetProperty("usable").GetBoolean()); }
    [Fact] public async Task Vehicle_detail_shows_the_causes() { var v = await VehicleWithDocuments(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Vehicle, v.Id, DocumentType.HuReport, new DateOnly(2026, 11, 5)); var body = await GetJson($"/api/v1/fleet/vehicles/{v.Id}"); Assert.Contains(body.GetProperty("causes").EnumerateArray(), x => x.GetProperty("documentType").GetString() == "hu_report"); }
    [Fact] public async Task Set_off_road_needs_a_reason() { var v = await VehicleWithDocuments(); using var response = await factory.AsDispatcher().PostAsJsonAsync($"/api/v1/fleet/vehicles/{v.Id}/off-road", new { version = v.Version, manualOffRoad = true, reason = " " }); Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode); Assert.Contains("reason", await response.Content.ReadAsStringAsync()); }
    [Fact] public async Task Hr_cannot_set_off_road() { var v = await VehicleWithDocuments(); using var response = await factory.AsHr().PostAsJsonAsync($"/api/v1/fleet/vehicles/{v.Id}/off-road", new { version = v.Version, manualOffRoad = true, reason = "safety" }); Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode); }
    [Fact] public async Task Set_off_road_on_a_retired_vehicle_conflicts() { var v = await VehicleWithDocuments(); await ReadinessTestSupport.SetVehicle(factory, v.Id, FleetOps.Modules.Fleet.VehicleStatus.Retired); using var response = await factory.AsDispatcher().PostAsJsonAsync($"/api/v1/fleet/vehicles/{v.Id}/off-road", new { version = v.Version, manualOffRoad = true, reason = "safety" }); Assert.Equal(HttpStatusCode.Conflict, response.StatusCode); Assert.Equal("state_conflict", await Code(response)); }
    [Fact] public async Task Set_off_road_writes_an_audit_entry() { var v = await VehicleWithDocuments(); using var response = await factory.AsDispatcher().PostAsJsonAsync($"/api/v1/fleet/vehicles/{v.Id}/off-road", new { version = v.Version, manualOffRoad = true, reason = "safety inspection" }); Assert.Equal(HttpStatusCode.OK, response.StatusCode); await using var c = await factory.DirectConnection(); await using var q = new Npgsql.NpgsqlCommand("select count(*) from fleetops.audit_entries where entity_id = @id and reason = 'safety inspection'", c); q.Parameters.AddWithValue("id", v.Id); Assert.Equal(1L, (long)(await q.ExecuteScalarAsync())!); }
    [Fact] public async Task Dispatcher_sees_a_medical_block_with_no_type() { var id = await BlockedMedical(); var body = await GetJson("/api/v1/readiness/drivers"); var row = body.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == id); Assert.DoesNotContain("medical", row.ToString(), StringComparison.OrdinalIgnoreCase); Assert.Null(row.GetProperty("causes")[0].GetProperty("documentType").GetString()); Assert.Equal("document_expired", row.GetProperty("causes")[0].GetProperty("code").GetString()); }
    [Fact] public async Task Dispatcher_sees_no_type_when_medical_is_one_of_several_causes() { var id = await BlockedMedical(); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Employee, id, DocumentType.Code95, new DateOnly(2026, 11, 5)); var body = await GetJson("/api/v1/readiness/drivers"); var row = body.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == id); Assert.Single(row.GetProperty("causes").EnumerateArray()); }
    [Fact] public async Task Dispatcher_sees_the_same_text_for_a_missing_medical() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); await using var c = await factory.DirectConnection(); await using var q = new Npgsql.NpgsqlCommand("delete from fleetops.documents where owner_id = @id and type = 'medical'", c); q.Parameters.AddWithValue("id", id); await q.ExecuteNonQueryAsync(); var body = await GetJson("/api/v1/readiness/drivers"); var row = body.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == id); Assert.Equal("document_missing", row.GetProperty("causes")[0].GetProperty("code").GetString()); Assert.Null(row.GetProperty("causes")[0].GetProperty("documentType").GetString()); }
    [Fact] public async Task Hr_sees_the_medical_type() { var id = await BlockedMedical(); var body = await GetJson("/api/v1/readiness/drivers", factory.AsHr()); var row = body.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == id); Assert.Equal("medical", row.GetProperty("causes")[0].GetProperty("documentType").GetString()); }
    [Fact] public async Task Dispatcher_sees_a_licence_block_with_its_type() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Employee, id, DocumentType.LicenceC_CE, new DateOnly(2026, 11, 5)); var body = await GetJson("/api/v1/readiness/drivers"); var row = body.GetProperty("items").EnumerateArray().Single(x => x.GetProperty("id").GetGuid() == id); Assert.Equal("licence_c_ce", row.GetProperty("causes")[0].GetProperty("documentType").GetString()); }
    [Fact] public async Task Summary_counts_usable_vehicles() { var v = await VehicleWithDocuments(); var body = await GetJson("/api/v1/readiness/summary"); Assert.True(body.GetProperty("vehiclesTotal").GetInt32() >= 1); Assert.True(body.GetProperty("vehiclesUsable").GetInt32() >= 1); }
    [Fact] public async Task Missing_lists_required_documents_with_no_row() { var v = await factory.CreateTruck(factory.AsDispatcher()); var body = await GetJson("/api/v1/documents?filter=missing", factory.AsDispatcher()); Assert.Equal(JsonValueKind.Array, body.GetProperty("items").ValueKind); Assert.DoesNotContain(body.GetProperty("items").EnumerateArray(), x => x.GetProperty("ownerId").GetGuid() == v.Id); }
    [Fact] public async Task Blocked_drivers_upload_sorts_first_in_the_queue() { var id = await BlockedMedical(); var body = await GetJson("/api/v1/readiness/drivers?blockedOnly=true", factory.AsDispatcher()); Assert.Equal(id, body.GetProperty("items")[0].GetProperty("id").GetGuid()); }
    [Fact] public async Task Driver_list_refuses_a_driver() { using var response = await factory.AsDriver().GetAsync("/api/v1/readiness/drivers"); Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode); }

    private async Task<VehicleDetail> VehicleWithDocuments() { var v = await factory.CreateTruck(factory.AsDispatcher()); await ReadinessTestSupport.AddAllVehicleDocuments(factory, v.Id); return v; }
    private async Task<Guid> BlockedMedical() { var id = Guid.NewGuid(); await ReadinessTestSupport.AddEmployee(factory, id); await ReadinessTestSupport.AddAllDriverDocuments(factory, id); await ReadinessTestSupport.AddDocument(factory, DocumentOwnerType.Employee, id, DocumentType.Medical, new DateOnly(2026, 11, 5)); return id; }
    private async Task<JsonElement> GetJson(string path, HttpClient? client = null) { using var response = await (client ?? factory.AsDispatcher()).GetAsync(path); response.EnsureSuccessStatusCode(); return (await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync())).RootElement.Clone(); }
    private static async Task<string> Code(HttpResponseMessage response) => (await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync())).RootElement.GetProperty("code").GetString()!;
}
